import { addMonths } from './src/dates.js';

const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });
const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

function nextCharge(sub, today) {
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

// Test the specific case
const gym = { cycle: 'monthly', since: '2026-09-02' };
const music = { cycle: 'monthly', since: '2026-09-30' };

console.log('Gym next charge:', nextCharge(gym, '2026-10-25'));
console.log('Music next charge:', nextCharge(music, '2026-10-25'));
"
